window.NLI_BIOGRAPHY_PATH_DATA = {"wyandanch":{"title":"Wyandanch: family, diplomacy, and agreements","mapLabel":"Sachem Wyandanch","note":"This path shows associated places from the story, not a precise travel route. Dated stops include document locations as well as journeys.","places":[{"label":"Montaukett homeland","eventTitle":"Wyandanch’s family connects Montauk with other Long Island communities","start_year":null,"sort_key":16360000,"dateLabel":"Before 1637; birth date unknown","place":"Montauk, East Hampton","coordinates":[-71.944,41.036],"reason":"Wyandanch belonged to the Montaukett community and was the younger brother of Poggatacut. Later family testimony connected his ancestry to Cattawamnuck land on the North Shore.","actionLabel":"family and homeland at Montauk"},{"label":"Peace and trade at Saybrook","eventTitle":"Wyandanch negotiates at Fort Saybrook during the Pequot War","start_year":1637,"sort_key":16370500,"dateLabel":"May 1637","place":"Old Saybrook, Connecticut","coordinates":[-72.351,41.284],"reason":"After the attack on the Pequot fort at Mystic, Wyandanch asked Lion Gardiner about peace and trade. Gardiner’s later account records his demand that Long Islanders kill Pequot refugees in return for trade, and Wyandanch’s consultation with his older brother.","actionLabel":"negotiates at Fort Saybrook"},{"label":"Named in the Hartford certificate","eventTitle":"A Hartford certificate names Wyandanch and three other sachems","start_year":1644,"sort_key":16440900,"dateLabel":"September 1644","place":"Hartford, Connecticut","coordinates":[-72.675,41.764],"reason":"At Youghco’s request, the United Colonies commissioners issued a certificate naming him, Wiantause (Wyandanch), Moughmaitow, and Weenagaminin. It recorded friendship with English and Dutch settlers and obligations imposed through the English tributary relationship.","actionLabel":"named in Hartford’s peace certificate"},{"label":"East Hampton agreement","eventTitle":"Wyandanch joins the East Hampton agreement with reserved Native uses","start_year":1648,"sort_key":16480429,"dateLabel":"April 29, 1648","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"Wyandanch, Poggatacut, Momoweta, and Nowedonah marked the East Hampton purchase; Chectanoo (Cockenoe) served as interpreter. The agreement reserved fishing, hunting, shell gathering for wampum, and portions of stranded whales.","actionLabel":"joins the East Hampton agreement"},{"label":"Southampton diplomacy","eventTitle":"Wyandanch negotiates during a Southampton murder crisis","start_year":1647,"sort_key":16490000,"dateLabel":"Late 1640s","place":"Southampton","coordinates":[-72.39,40.885],"reason":"Gardiner recalled guaranteeing Wyandanch’s safety while he went to Southampton after an English woman was killed. Later Halsey and Sayre testimony described Mandush’s acknowledgment of Wyandanch, a relationship invoked in subsequent Shinnecock land transactions.","actionLabel":"negotiates during the Southampton crisis"},{"label":"Montaukett conflict and captivity","eventTitle":"Wyandanch’s daughter and other Montauketts are taken captive","start_year":1653,"sort_key":16530000,"dateLabel":"1653","place":"Montauk, East Hampton","coordinates":[-71.944,41.036],"reason":"A raid by Ninigret’s forces brought deaths and captivity to the Montauketts. Wyandanch’s daughter was among the captives, setting in motion ransom negotiations that continued into 1654.","actionLabel":"family faces captivity at Montauk"},{"label":"Appeal for his daughter and fellow captives","eventTitle":"Thomas James sends Wyandanch’s urgent appeal for the captives","start_year":1654,"sort_key":16540906,"dateLabel":"September 6, 1654","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"Writing from East Hampton to John Winthrop Jr. at Wyandanch’s request, Thomas James asked that ransom wampum reportedly intercepted by Thomas Stanton be forwarded. Wyandanch feared for his daughter and the other captives and sought their return even at risk of losing the payment.","actionLabel":"seeks help to recover captives"},{"label":"Sea journey through Milford","eventTitle":"Contrary winds bring Wyandanch’s party to Milford","start_year":1656,"sort_key":16560800,"dateLabel":"Late August 1656","place":"Milford, Connecticut","coordinates":[-73.055,41.222],"reason":"Wyandanch and five companions sailed in Captain Youngs’s vessel toward the commissioners’ meeting at Plymouth. Winds brought them first to Milford, where he sought out people associated with accusations against him.","actionLabel":"lands at Milford before the hearing"},{"label":"Hearing before the commissioners","eventTitle":"Wyandanch answers Ninigret’s representative at Plymouth","start_year":1656,"sort_key":16560900,"dateLabel":"September 1656","place":"Plymouth, Massachusetts","coordinates":[-70.667,41.958],"reason":"The commissioners found the allegation of a hired poisoning plot unsupported. They could not settle conflicting accounts of a peace agreement before violence at Block Island, continued protection measures, and deferred Wyandanch’s tribute arrears.","actionLabel":"answers accusations at Plymouth"},{"label":"Hempstead and Merrick connections","eventTitle":"Wyandanch joins the Hempstead purchase confirmation","start_year":1657,"sort_key":16570704,"dateLabel":"July 4, 1657","place":"Hempstead","coordinates":[-73.619,40.707],"reason":"The confirmation names people of Massapequa, Mericoke, and Rockaway and records the Montauk sachem as Wantagh. Tackapousha, Chegonoe (Cockenoe), and other Native participants also marked it.","actionLabel":"joins the Hempstead confirmation"},{"label":"Horse Neck confirmation at Shelter Island","eventTitle":"Wyandanch confirms the Horse Neck transaction at Shelter Island","start_year":1658,"sort_key":16580514,"dateLabel":"May 14, 1658","place":"Shelter Island","coordinates":[-72.35,41.066],"reason":"At Shelter Island, Wyandanch confirmed the title to Horse Neck, now Lloyd Neck, for Samuel Andrews after an earlier sale. The document links the East End leader with a disputed western North Shore property.","actionLabel":"confirms Horse Neck’s sale at Shelter Island"},{"label":"Grazing, whales, and mat-making plants","eventTitle":"Wyandanch and Wyancombone reserve whale and mat-making rights","start_year":1658,"sort_key":16580610,"dateLabel":"June 10, 1658","place":"Shinnecock and Quogue shoreline","coordinates":[-72.542,40.802],"reason":"Their agreement with Lion Gardiner allowed beach grazing and required annual payment of twenty-five shillings. Stranded whales and summer gathering of flags and bulrushes remained reserved to the entitled Native people. David Gardiner witnessed it.","actionLabel":"reserves whales and mat-making plants"},{"label":"Cockenoe marks the South Shore meadows","eventTitle":"Wyandanch appoints Cockenoe to deliver and mark meadowlands","start_year":1658,"sort_key":16580817,"dateLabel":"August 17, 1658","place":"Huntington South Shore meadows","coordinates":[-73.41,40.677],"reason":"The Huntington agreement named Cockenoe as Wyandanch’s agent, with separate compensation for marking three South Shore necks. Lion Gardiner was to hold the deed until the conditions were met; Wyandanch and Tackapousha acknowledged payment on May 23, 1659.","actionLabel":"sends Cockenoe to mark meadowlands"},{"label":"Canoe case at East Hampton","eventTitle":"Wyandanch wins compensation for his damaged canoe","start_year":1659,"sort_key":16590125,"dateLabel":"January 25, 1658/59","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"East Hampton’s court heard Wyandanch’s case against Jeremy Vaile. Lion Gardiner and John Rose described its use, repairs, and damage; the jury awarded ten shillings and court charges.","actionLabel":"wins damages for his canoe"},{"label":"Family claims on the North Fork","eventTitle":"Wyandanch asserts family interests in Corchaug land","start_year":1659,"sort_key":16590130,"dateLabel":"January 30, 1659","place":"Southold","coordinates":[-72.425,41.066],"reason":"At a Southold meeting recorded by William Wells, Wyandanch invoked inherited family interests. The account describes Corchaug leaders’ silence, rather than recording their assent.","actionLabel":"asserts family interests at Southold"},{"label":"Plum Island agreement","eventTitle":"Wyandanch’s Plum Island agreement is dated at Gardiners Island","start_year":1659,"sort_key":16590427,"dateLabel":"April 27, 1659","place":"Gardiners Island","coordinates":[-72.104,41.092],"reason":"The agreement with Samuel Wyllys of Hartford concerned Plum Island. Southold’s published records list a coat, biscuit, and fish hooks among its consideration and identify Gardiners Island as the place where it was dated.","actionLabel":"makes the Plum Island agreement"},{"label":"Quogue agreement with John Ogden","eventTitle":"Wyandanch and his son enter the Quogue agreement with John Ogden","start_year":1659,"sort_key":16590512,"dateLabel":"May 12, 1659","place":"Shinnecock and Quogue shoreline","coordinates":[-72.542,40.802],"reason":"The agreement concerned lands west of Canoe Place toward Peaconock, including West Woods, and was connected to the Shinnecock fine. A 1665 order directed the annual payment to Wyandanch’s daughter and heir.","actionLabel":"enters the Quogue agreement"},{"label":"Family deed to Lion Gardiner","eventTitle":"Wyandanch, his wife, and Wyancombone give land to Lion Gardiner","start_year":1659,"sort_key":16590714,"dateLabel":"July 14, 1659","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"The East Hampton deed conveyed land between Huntington and Setauket and credited Gardiner’s counsel, assistance in war, and help ransoming their daughter and friends. All three family members marked it.","actionLabel":"family signs the Gardiner deed"},{"label":"Unkechaug beach whale rights","eventTitle":"Wyandanch makes a further whale-rights agreement with Gardiner","start_year":1659,"sort_key":16590728,"dateLabel":"July 28, 1659","place":"Unkechaug South Shore","coordinates":[-72.834,40.748],"reason":"Wyandanch and Wyancombone’s twenty-one-year agreement named local sachems’ consent, reserved fins and tails to Native people, and required payment for whale bodies and bones. David Gardiner witnessed it.","actionLabel":"grants whale rights to Gardiner"},{"label":"Wyandanch’s death and family succession","eventTitle":"Wyandanch dies during a period of severe Native mortality","start_year":1659,"sort_key":16591200,"dateLabel":"Later in 1659","place":"Montauk, East Hampton","coordinates":[-71.944,41.036],"reason":"Gardiner’s 1660 account mourned Wyandanch as a friend and brother. It claimed poisoning without naming a perpetrator or providing corroboration. His wife and children continued to appear in leadership and land records.","actionLabel":"remembered through his family’s continuing history"}]},"wuchikittawbut":{"title":"Wuchikittawbut, Montaukett Sunksquaw — life and connections","mapLabel":"Wuchikittawbut","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Wuchikittawbut marks the family deed to Lion Gardiner","eventTitle":"Wuchikittawbut marks the family deed to Lion Gardiner","start_year":1659,"sort_key":16590714,"dateLabel":"July 14, 1659","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"Wuchikittawbut, Wyandanch, and Wyancombone marked the deed concerning land between Huntington and Setauket. It connected the grant with Gardiner’s counsel and assistance in recovering their daughter and other captives.","actionLabel":"Wuchikittawbut marks the family deed to Lion Gardiner"},{"label":"Wyandanch’s widow and son confirm the Gardiner agreement","eventTitle":"Wyandanch’s widow and son confirm the Gardiner agreement","start_year":1660,"sort_key":16600406,"dateLabel":"April 6, 1660","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"The continuation attached to the family deed recorded the widow’s and son’s confirmation after Wyandanch’s death. Their participation carried the family’s land business into a new generation.","actionLabel":"Wyandanch’s widow and son confirm the Gardiner agreement"},{"label":"Wuchikittawbut and Montaukett proprietors enter the Montauk agreement","eventTitle":"Wuchikittawbut and Montaukett proprietors enter the Montauk agreement","start_year":1660,"sort_key":16600800,"dateLabel":"August 1660","place":"Montauk","coordinates":[-71.944,41.036],"reason":"The indenture named the widow, Wyancombone, Cockenoe, Pauquatoun, and other Native proprietors. It promised £100 in ten annual payments. A counterbond allowed a return to Montauk when safe, with payments withheld during their residence and the English title claim maintained.","actionLabel":"Wuchikittawbut and Montaukett proprietors enter the Montauk agreement"},{"label":"Wuchikittawbut answers questions about her deceased son","eventTitle":"Wuchikittawbut answers questions about her deceased son","start_year":1662,"sort_key":16621201,"dateLabel":"December 1, 1662","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"Lion Gardiner, Thomas James, and Richard Shaw recorded her statement that Wyancombone had died aged twenty-two and had been twenty-one when a deed of gift was made the preceding year. The question connected his age with the land transaction.","actionLabel":"Wuchikittawbut answers questions about her deceased son"},{"label":"Wuchikittawbut demands the whale payments owed to her","eventTitle":"Wuchikittawbut demands the whale payments owed to her","start_year":1663,"sort_key":16630114,"dateLabel":"January 14, 1662/63","place":"Shinnecock and Quogue shoreline","coordinates":[-72.542,40.802],"reason":"She recalled sending Cockenoe and Tobis to mark John Cooper’s beach limits, had the bounds established again that winter, and demanded payment for whales according to their covenant. This declaration records her living and exercising authority in January 1663.","actionLabel":"Wuchikittawbut demands the whale payments owed to her"}]},"nasseconset-sachem-of-the-nissequogue":{"title":"Nasseconset, Sachem of the Nissequogue — life and connections","mapLabel":"Nasseconset","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Nasseconset makes an agreement with a specified payment deadline","eventTitle":"Nasseconset makes an agreement with a specified payment deadline","start_year":1650,"sort_key":16500000,"dateLabel":"1650","place":"Nissequogue River and Smithtown","coordinates":[-73.204,40.882],"reason":"The Nasseconseke agreement names English purchasers including the Wood family, Daniel Whitehead, and Stephen Hudson. Coats, wampum, tools, kettles, and muxes were to be paid by September 29, 1650.","actionLabel":"Nasseconset makes an agreement with a specified payment deadline"},{"label":"Nasseconset challenges Richard Smith’s occupation","eventTitle":"Nasseconset challenges Richard Smith’s occupation","start_year":1664,"sort_key":16640000,"dateLabel":"1664","place":"Setauket","coordinates":[-73.111,40.945],"reason":"In Smith’s account, Nasseconset complained at the Setauket court that Smith had taken his land. He distinguished the Cattawamnuck grant from land extending toward the Nissequogue River that he claimed as his own.","actionLabel":"Nasseconset challenges Richard Smith’s occupation"},{"label":"Nasseconset and fellow claimants settle with Richard Smith","eventTitle":"Nasseconset and fellow claimants settle with Richard Smith","start_year":1665,"sort_key":16650504,"dateLabel":"May 4, 1665","place":"Nissequogue River and Smithtown","coordinates":[-73.204,40.882],"reason":"After the 1664 complaint and further consultation, Smith compensated Nasseconset and Catawump. The deed marked by Nesatesconsett, Catawump, and Tanaringo retained interests described as mats, canoes, eagles, and deer skins taken in the water.","actionLabel":"Nasseconset and fellow claimants settle with Richard Smith"},{"label":"Family testimony explains overlapping Nissequogue land interests","eventTitle":"Family testimony explains overlapping Nissequogue land interests","start_year":1666,"sort_key":16660622,"dateLabel":"June 22, 1666","place":"Nissequogue River and Smithtown","coordinates":[-73.204,40.882],"reason":"Pauquatoun recalled Wyandanch’s grandmother living on Cattawamnuck land. Quashawam explained relatives’ interests and their expected share of the payment. This testimony adds family memory to the dispute involving Nasseconset.","actionLabel":"Family testimony explains overlapping Nissequogue land interests"}]},"sunksqua-weany-pametsechs":{"title":"Sunksqua Weany — life and connections","mapLabel":"Weany","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Weany and fellow Shinnecock proprietors mark the Topping agreement","eventTitle":"Weany and fellow Shinnecock proprietors mark the Topping agreement","start_year":1662,"sort_key":16620410,"dateLabel":"April 10, 1662","place":"Quogue and Quantuck","coordinates":[-72.581,40.823],"reason":"Weany, Anabackus, and Jackanapes negotiated with Thomas Topping over land from Canoe Place toward Seatuck. Other interested Native people also marked the deed. Payment was eighty fathoms of wampum or an equivalent; the bargain conveyed half the profits from stranded whales on the specified beach.","actionLabel":"Weany and fellow Shinnecock proprietors mark the Topping agreement"},{"label":"Other Shinnecock landholders challenge Weany’s earlier agreement","eventTitle":"Other Shinnecock landholders challenge Weany’s earlier agreement","start_year":1666,"sort_key":16660917,"dateLabel":"September 17, 1666","place":"Southampton","coordinates":[-72.389,40.884],"reason":"A protest asserted that Weany and her associates lacked the right to convey the tract. Mandush’s daughter and widow were among the signers. They conditionally assigned their own interests to Southampton, subject to a finding by Governor Nicolls and payment. The document records their objection, not Weany’s withdrawal.","actionLabel":"Other Shinnecock landholders challenge Weany’s earlier agreement"}]},"cockenoe":{"title":"Cockenoe (de Long Island) — life and connections","mapLabel":"Cockenoe","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Eliot’s unnamed Long Island teacher is later identified with Cockenoe","eventTitle":"Eliot’s unnamed Long Island teacher is later identified with Cockenoe","start_year":1637,"sort_key":16370000,"dateLabel":"1637 and the 1640s","place":"Dorchester, Massachusetts","coordinates":[-71.057,42.301],"reason":"Eliot described a Long Island man captured during the Pequot War and living in Richard Collicott’s household at Dorchester. Tooker later identified this teacher with Cockenoe by comparing origin, language skills, and chronology. The identification is a historical reconstruction.","actionLabel":"Eliot’s unnamed Long Island teacher is later identified with Cockenoe"},{"label":"Cockenoe is appointed interpreter for the East Hampton purchase","eventTitle":"Cockenoe is appointed interpreter for the East Hampton purchase","start_year":1648,"sort_key":16480429,"dateLabel":"April 29, 1648","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"The deed appoints Chectanoo to interpret between Native parties and English purchasers. Its terms include continuing Native hunting, fishing, shell gathering, and whale interests.","actionLabel":"Cockenoe is appointed interpreter for the East Hampton purchase"},{"label":"Eliot describes the linguistic work of his first Native teacher","eventTitle":"Eliot describes the linguistic work of his first Native teacher","start_year":1649,"sort_key":16490200,"dateLabel":"February 1648/49","place":"Dorchester, Massachusetts","coordinates":[-71.057,42.301],"reason":"Eliot’s letter credits an unnamed Native teacher with teaching words, interpretation, and assistance translating prayers and scripture. Tooker’s later biography associates him with Cockenoe.","actionLabel":"Eliot describes the linguistic work of his first Native teacher"},{"label":"Cockenoe appears in the Norwalk purchase","eventTitle":"Cockenoe appears in the Norwalk purchase","start_year":1652,"sort_key":16520200,"dateLabel":"February 1651/52","place":"Norwalk","coordinates":[-73.414,41.1],"reason":"Tooker traces Cockenoe-de-Long Island in the Norwalk transaction and connects his name with the island off the Connecticut coast. The record extends his interpreting work across Long Island Sound.","actionLabel":"Cockenoe appears in the Norwalk purchase"},{"label":"Cockenoe defends Shelter Island residents against removal","eventTitle":"Cockenoe defends Shelter Island residents against removal","start_year":1652,"sort_key":16520902,"dateLabel":"September 2, 1652","place":"Shelter Island","coordinates":[-72.338,41.067],"reason":"Before the United Colonies commissioners, Checkanoe explained that Native residents had granted James Forrett a limited area marked by trees without surrendering their homes. Their complaint was referred to New Haven for examination.","actionLabel":"Cockenoe defends Shelter Island residents against removal"},{"label":"Cockenoe witnesses the Hempstead confirmation","eventTitle":"Cockenoe witnesses the Hempstead confirmation","start_year":1657,"sort_key":16570704,"dateLabel":"July 4, 1657","place":"Hempstead and Merrick","coordinates":[-73.62,40.709],"reason":"Chegonoe appears as a witness in the agreement involving Wyandanch and Tackapousha. Subsequent Hempstead instructions sent townsmen with him to mark boundaries.","actionLabel":"Cockenoe witnesses the Hempstead confirmation"},{"label":"Cockenoe is paid to mark the South Shore meadow bounds","eventTitle":"Cockenoe is paid to mark the South Shore meadow bounds","start_year":1658,"sort_key":16580817,"dateLabel":"August 17, 1658","place":"Huntington South Shore meadows","coordinates":[-73.41,40.677],"reason":"The Huntington agreement specified a coat, powder, lead, a hatchet, and wampum for Cockenoe’s boundary work. Wyandanch’s May 23, 1659 receipt refers to the meadows he had marked.","actionLabel":"Cockenoe is paid to mark the South Shore meadow bounds"},{"label":"Cockenoe joins the widow and son in the Montauk agreement","eventTitle":"Cockenoe joins the widow and son in the Montauk agreement","start_year":1660,"sort_key":16600800,"dateLabel":"August 1660","place":"Montauk","coordinates":[-71.944,41.036],"reason":"Chekanow appears with Wuchikittawbut, Wyancombone, Pauquatoun, and other Native proprietors in the Montauk indenture and its provisions concerning payment and residence.","actionLabel":"Cockenoe joins the widow and son in the Montauk agreement"},{"label":"Pauquatoun recalls Cockenoe’s boundary work","eventTitle":"Pauquatoun recalls Cockenoe’s boundary work","start_year":1667,"sort_key":16671018,"dateLabel":"October 18, 1667","place":"Nissequogue River and Smithtown","coordinates":[-73.204,40.882],"reason":"Pauquatoun testified that Wyandanch had appointed Sakkatakka and Chekanno to mark Rattaconeck land and had approved the marked bounds. This is testimony about Cockenoe, not a deposition by him.","actionLabel":"Pauquatoun recalls Cockenoe’s boundary work"},{"label":"Cockenoe and Montaukett leaders reject Ninigret’s tribute claim","eventTitle":"Cockenoe and Montaukett leaders reject Ninigret’s tribute claim","start_year":1669,"sort_key":16691103,"dateLabel":"November 3, 1669","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"Checkannoo and other leaders rejected the claimed submission and declared that further tribute required the approval of the New York governor.","actionLabel":"Cockenoe and Montaukett leaders reject Ninigret’s tribute claim"},{"label":"Cockenoe joins the Montauk land-between-the-ponds agreement","eventTitle":"Cockenoe joins the Montauk land-between-the-ponds agreement","start_year":1670,"sort_key":16701201,"dateLabel":"December 1, 1670","place":"Montauk","coordinates":[-71.944,41.036],"reason":"Chekonnow appears with Poniuts, also called Mousup, and other Native participants in the conveyance to John Mulford, Thomas James, and Jeremiah Conkling.","actionLabel":"Cockenoe joins the Montauk land-between-the-ponds agreement"},{"label":"Cockenoe joins a shore-whaling enterprise","eventTitle":"Cockenoe joins a shore-whaling enterprise","start_year":1675,"sort_key":16750704,"dateLabel":"July 4, 1675","place":"Shinnecock and Quogue shoreline","coordinates":[-72.542,40.802],"reason":"The agreement with James Schellinger and James Loper included transporting the catch and trying out oil, with compensation expressed as a share of the profits.","actionLabel":"Cockenoe joins a shore-whaling enterprise"},{"label":"Cockenoe interprets land claims before the governor and council","eventTitle":"Cockenoe interprets land claims before the governor and council","start_year":1677,"sort_key":16770623,"dateLabel":"June 23, 1677","place":"Lower Manhattan / colonial council","coordinates":[-74.006,40.705],"reason":"The hearing concerned Hempstead and competing Native claims. Tooker identifies Cockenoe as interpreting the statements of Weamsko and Swaneme.","actionLabel":"Cockenoe interprets land claims before the governor and council"},{"label":"Montauk accounts record Cockenoe’s work with corn and burning","eventTitle":"Montauk accounts record Cockenoe’s work with corn and burning","start_year":1682,"sort_key":16820000,"dateLabel":"1682","place":"Montauk","coordinates":[-71.944,41.036],"reason":"Accounts recorded payments for keeping corn and burning Montauk. The entries connect his later career with tending and managing the landscape.","actionLabel":"Montauk accounts record Cockenoe’s work with corn and burning"},{"label":"Cockenoe marks another Montauk conveyance","eventTitle":"Cockenoe marks another Montauk conveyance","start_year":1687,"sort_key":16870803,"dateLabel":"August 3, 1687","place":"Montauk","coordinates":[-71.944,41.036],"reason":"Tooker follows Cockenoe’s documented career to the August 1687 conveyance concerning land at Montauk. This is a surviving dated appearance, not a recorded death date.","actionLabel":"Cockenoe marks another Montauk conveyance"}]},"momoweta":{"title":"Momoweta — life and connections","mapLabel":"Momoweta","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Momoweta is named in the United Colonies certificate","eventTitle":"Momoweta is named in the United Colonies certificate","start_year":1644,"sort_key":16440900,"dateLabel":"September 1644","place":"Hartford","coordinates":[-72.683,41.765],"reason":"The certificate names Moughmaitow with Youghco, Wiantause, and Weenagaminin. Youghco requested it and is the person recorded as present. Momoweta’s inclusion does not establish his personal attendance at Hartford.","actionLabel":"Momoweta is named in the United Colonies certificate"},{"label":"Momoweta joins the East Hampton agreement","eventTitle":"Momoweta joins the East Hampton agreement","start_year":1648,"sort_key":16480429,"dateLabel":"April 29, 1648","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"The Corchaug sachem appears with Poggatacut, Wyandanch, and Nowedonah. The Native parties retained hunting, fishing, shell gathering for wampum, and a share of stranded whales; Chectanoo was appointed interpreter.","actionLabel":"Momoweta joins the East Hampton agreement"},{"label":"Mammawetough appears in the eastern North Fork deed","eventTitle":"Mammawetough appears in the eastern North Fork deed","start_year":1648,"sort_key":16480500,"dateLabel":"May 1648","place":"Eastern North Fork / Oyster Ponds","coordinates":[-72.302,41.144],"reason":"Tooker identifies the Corchaug sachem in the Hashamomuk and Oyster Ponds conveyance to New Haven purchasers. The land concerned included the eastern North Fork and Plum Island.","actionLabel":"Mammawetough appears in the eastern North Fork deed"}]},"poggatacut-sachem-of-the-manhassets-of-shelter-island":{"title":"Poggatacut, Sachem of the Manhassets of Shelter Island — life and connections","mapLabel":"Poggatacut","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Wyandanch consults his elder brother during the Pequot War","eventTitle":"Wyandanch consults his elder brother during the Pequot War","start_year":1637,"sort_key":16370000,"dateLabel":"1637","place":"Shelter Island","coordinates":[-72.338,41.067],"reason":"Gardiner’s later account describes Wyandanch seeking the advice of his elder brother, the sachem living on Shelter Island, before responding to demands concerning Pequot refugees.","actionLabel":"Wyandanch consults his elder brother during the Pequot War"},{"label":"Yovawan and Aswaw convey Manchonat to Lion Gardiner","eventTitle":"Yovawan and Aswaw convey Manchonat to Lion Gardiner","start_year":1639,"sort_key":16390503,"dateLabel":"May 3, 1639","place":"Gardiners Island","coordinates":[-72.104,41.092],"reason":"The deed names Yovawan and his wife Aswaw and records ten coats of trading cloth as payment. J. Hammond Trumbull later suggested Yovawan may have been Wyandanch’s elder brother, Poggatacut; the identification is not stated in the deed.","actionLabel":"Yovawan and Aswaw convey Manchonat to Lion Gardiner"},{"label":"Youghco requests a certificate at Hartford","eventTitle":"Youghco requests a certificate at Hartford","start_year":1644,"sort_key":16440900,"dateLabel":"September 1644","place":"Hartford","coordinates":[-72.683,41.765],"reason":"The United Colonies commissioners issued the certificate at Youghco’s request, naming him with Wiantause, Moughmaitow, and Weenagaminin. It recorded friendship with English and Dutch settlers and colonial expectations of tribute and responsibility.","actionLabel":"Youghco requests a certificate at Hartford"},{"label":"Poggatacut joins the East Hampton agreement","eventTitle":"Poggatacut joins the East Hampton agreement","start_year":1648,"sort_key":16480429,"dateLabel":"April 29, 1648","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"Poggatacut, Wyandanch, Momoweta, and Nowedonah appear together. The Native parties retained hunting, fishing, wampum-shell gathering, and a share of stranded whales.","actionLabel":"Poggatacut joins the East Hampton agreement"}]},"sachem-tackapousha":{"title":"Sachem Tackapousha — life and connections","mapLabel":"Tackapousha","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Tackapousha makes an agreement with New Netherland","eventTitle":"Tackapousha makes an agreement with New Netherland","start_year":1656,"sort_key":16560312,"dateLabel":"March 12, 1656","place":"Massapequa","coordinates":[-73.474,40.671],"reason":"The treaty linked peace and trade and promised a fortified trading place. It connects Tackapousha’s diplomacy with the history of Fort Massapeag.","actionLabel":"Tackapousha makes an agreement with New Netherland"},{"label":"Tackapousha sends representatives to return stolen goods","eventTitle":"Tackapousha sends representatives to return stolen goods","start_year":1656,"sort_key":16560930,"dateLabel":"September 30, 1656","place":"Lower Manhattan / colonial council","coordinates":[-74.006,40.705],"reason":"Massapequa representatives told the Dutch council that their sachem had ordered restitution. The council thanked them through interpreter Lawrens Hansen and promised reciprocal action when thefts were reported.","actionLabel":"Tackapousha sends representatives to return stolen goods"},{"label":"Tackapousha joins the Hempstead confirmation","eventTitle":"Tackapousha joins the Hempstead confirmation","start_year":1657,"sort_key":16570704,"dateLabel":"July 4, 1657","place":"Hempstead and Merrick","coordinates":[-73.62,40.709],"reason":"The confirmation connected Tackapousha, Wyandanch, Cockenoe, and other participants with Hempstead’s land and boundary claims. Later disputes show that acknowledgment did not settle every question of payment.","actionLabel":"Tackapousha joins the Hempstead confirmation"},{"label":"Tackapousha and Wyandanch acknowledge the meadow payment","eventTitle":"Tackapousha and Wyandanch acknowledge the meadow payment","start_year":1659,"sort_key":16590523,"dateLabel":"May 23, 1659","place":"Huntington South Shore meadows","coordinates":[-73.41,40.677],"reason":"The receipt concerns South Shore meadows Cockenoe had marked under the August 1658 Huntington agreement.","actionLabel":"Tackapousha and Wyandanch acknowledge the meadow payment"},{"label":"Quashawam describes family connections involving Tackapousha","eventTitle":"Quashawam describes family connections involving Tackapousha","start_year":1666,"sort_key":16660622,"dateLabel":"June 22, 1666","place":"Nissequogue River and Smithtown","coordinates":[-73.204,40.882],"reason":"Quashawam’s recorded testimony linked Tackapousha with her parents and sachems interested in the Cattawamnuck lands. She explained that relatives were to share the payment.","actionLabel":"Quashawam describes family connections involving Tackapousha"},{"label":"Tackapousha challenges Hempstead over unpaid Mericock land","eventTitle":"Tackapousha challenges Hempstead over unpaid Mericock land","start_year":1675,"sort_key":16750805,"dateLabel":"August 5, 1675","place":"Hempstead and Merrick","coordinates":[-73.62,40.709],"reason":"At the colonial council, Tackapousha asserted that Hempstead had not paid. Native parties rejected the Montaukett sachem’s alleged right to give their land away and asked time to consult before proposing compensation.","actionLabel":"Tackapousha challenges Hempstead over unpaid Mericock land"},{"label":"Tackapousha’s petition brings Hempstead before the council","eventTitle":"Tackapousha’s petition brings Hempstead before the council","start_year":1683,"sort_key":16831009,"dateLabel":"October 9–22, 1683","place":"Lower Manhattan / colonial council","coordinates":[-74.006,40.705],"reason":"The council ordered Hempstead’s inhabitants to explain the disturbance of Native possessions. On October 22, after their appearance, the petition was referred to the Court of Assizes.","actionLabel":"Tackapousha’s petition brings Hempstead before the council"}]},"ninigret-eastern-niantic-sachem":{"title":"Ninigret, Eastern Niantic Sachem — life and connections","mapLabel":"Ninigret","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Ninigret’s Eastern Niantic homeland","eventTitle":"Ninigret’s Eastern Niantic homeland","start_year":null,"sort_key":0,"dateLabel":"Seventeenth century","place":"Eastern Niantic homeland, Rhode Island","coordinates":[-71.64,41.39],"reason":"Ninigret, also called Janemo, was an Eastern Niantic sachem whose diplomacy connected Rhode Island, Long Island, and neighboring Native and colonial powers.","actionLabel":"Ninigret’s Eastern Niantic homeland"},{"label":"Ninigret’s conflict with the Montauketts brings captivity and ransom","eventTitle":"Ninigret’s conflict with the Montauketts brings captivity and ransom","start_year":1653,"sort_key":16530000,"dateLabel":"1653","place":"Montauk","coordinates":[-71.944,41.036],"reason":"Colonial records describe attacks and captives, including Wyandanch’s daughter. James’s September 1654 letter reports the effort to forward her ransom.","actionLabel":"Ninigret’s conflict with the Montauketts brings captivity and ransom"},{"label":"Ninigret rejects accusations of a Dutch war agreement","eventTitle":"Ninigret rejects accusations of a Dutch war agreement","start_year":1653,"sort_key":16530400,"dateLabel":"April 1653","place":"Eastern Niantic homeland, Rhode Island","coordinates":[-71.64,41.39],"reason":"In answers preserved by the United Colonies commissioners, Ninigret denied planning an attack and asked why he would risk his family and country for weapons. He distinguished news of war in Europe from an agreement to fight in New England.","actionLabel":"Ninigret rejects accusations of a Dutch war agreement"},{"label":"United Colonies intervention targets Ninigret and Pequot dependents","eventTitle":"United Colonies intervention targets Ninigret and Pequot dependents","start_year":1654,"sort_key":16540000,"dateLabel":"1654","place":"Eastern Niantic homeland, Rhode Island","coordinates":[-71.64,41.39],"reason":"The commissioners ordered an armed intervention under Major Simon Willard and made demands concerning Pequots living under Ninigret’s authority. The dispute involved tribute, protection, and colonial jurisdiction.","actionLabel":"United Colonies intervention targets Ninigret and Pequot dependents"},{"label":"Commissioners hear allegations involving Ninigret, Wyandanch, and Uncas","eventTitle":"Commissioners hear allegations involving Ninigret, Wyandanch, and Uncas","start_year":1656,"sort_key":16560900,"dateLabel":"September 1656","place":"Plymouth, Massachusetts","coordinates":[-70.668,41.958],"reason":"Wyandanch appeared in response to allegations of a poisoning plot concerning Uncas. The commissioners did not receive the proof needed to sustain Ninigret’s accusations.","actionLabel":"Commissioners hear allegations involving Ninigret, Wyandanch, and Uncas"},{"label":"Ninigret reports Wyandanch’s daughter dead and asserts tribute claims","eventTitle":"Ninigret reports Wyandanch’s daughter dead and asserts tribute claims","start_year":1669,"sort_key":16690700,"dateLabel":"July 1669","place":"Newport, Rhode Island","coordinates":[-71.31,41.49],"reason":"The Rhode Island testimony described by Tooker asserted authority over the Montauketts. Their leaders formally rejected the claimed submission that November.","actionLabel":"Ninigret reports Wyandanch’s daughter dead and asserts tribute claims"},{"label":"Ninigret stays out of King Philip’s War","eventTitle":"Ninigret stays out of King Philip’s War","start_year":1675,"sort_key":16750000,"dateLabel":"1675–1676","place":"Eastern Niantic homeland, Rhode Island","coordinates":[-71.64,41.39],"reason":"Lorén Spears’s museum account places Ninigret’s neutrality within the survival of Niantic and Narragansett people through the war’s devastating consequences.","actionLabel":"Ninigret stays out of King Philip’s War"},{"label":"Ninigret dies after a long diplomatic career","eventTitle":"Ninigret dies after a long diplomatic career","start_year":1677,"sort_key":16770000,"dateLabel":"1677","place":"Eastern Niantic homeland, Rhode Island","coordinates":[-71.64,41.39],"reason":"Spears dates Ninigret’s death to 1677. His life connected Rhode Island, Long Island, and the competing Native and colonial powers around the Sound.","actionLabel":"Ninigret dies after a long diplomatic career"}]},"quashawam":{"title":"Quashawam — life and connections","mapLabel":"Quashawam","note":"Places connected with the dated records, including homelands, agreements, and testimony.","places":[{"label":"Wyandanch’s daughter is taken captive during the Niantic conflict","eventTitle":"Wyandanch’s daughter is taken captive during the Niantic conflict","start_year":1653,"sort_key":16530000,"dateLabel":"1653","place":"Montauk","coordinates":[-71.944,41.036],"reason":"The captivity led to the ransom efforts described in Thomas James’s September 1654 letter and Gardiner’s later account. Later histories identify the daughter as Quashawam.","actionLabel":"Wyandanch’s daughter is taken captive during the Niantic conflict"},{"label":"Thomas James appeals for the delivery of the ransom","eventTitle":"Thomas James appeals for the delivery of the ransom","start_year":1654,"sort_key":16540906,"dateLabel":"September 6, 1654","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"James wrote to John Winthrop Jr. about the delayed ransom for Wyandanch’s daughter and other captives, asking for intervention concerning Thomas Stanton.","actionLabel":"Thomas James appeals for the delivery of the ransom"},{"label":"Quashawam and Shinnecock representatives make a league","eventTitle":"Quashawam and Shinnecock representatives make a league","start_year":1664,"sort_key":16640211,"dateLabel":"February 11, 1663/64","place":"Southampton","coordinates":[-72.389,40.884],"reason":"The agreement addresses leadership, tribute, succession, conflict, and payment of the remaining fire debt. Quashawam marked it with Quaquashaug, Iaskhonse, Accabaco, and Appanch.","actionLabel":"Quashawam and Shinnecock representatives make a league"},{"label":"Quashawam authorizes John Scott to conduct land business","eventTitle":"Quashawam authorizes John Scott to conduct land business","start_year":1664,"sort_key":16640211,"dateLabel":"February 11, 1663/64","place":"Southampton","coordinates":[-72.389,40.884],"reason":"A separate authorization empowered Scott to demand payments for lands bought but unpaid and to conduct further transactions. Its broad terms put extensive power over business in her name into his hands.","actionLabel":"Quashawam authorizes John Scott to conduct land business"},{"label":"A Jamaica transaction includes payment to Quashawam","eventTitle":"A Jamaica transaction includes payment to Quashawam","start_year":1664,"sort_key":16640225,"dateLabel":"February 25, 1663/64","place":"Jamaica","coordinates":[-73.795,40.702],"reason":"The transaction included an order for twelve looking glasses to be delivered to Quashawam. The transaction connected Scott’s business with her family’s western land claims.","actionLabel":"A Jamaica transaction includes payment to Quashawam"},{"label":"Quashawam answers Richard Smith about Nasseconset’s claim","eventTitle":"Quashawam answers Richard Smith about Nasseconset’s claim","start_year":1665,"sort_key":16650000,"dateLabel":"Before May 4, 1665","place":"East Hampton","coordinates":[-72.185,40.964],"reason":"Smith’s account describes her acknowledgment of earlier dealings involving her father and brother without a written instrument resolving his claim. His account precedes the settlement dated May 4, 1665.","actionLabel":"Quashawam answers Richard Smith about Nasseconset’s claim"},{"label":"The court preserves the annual payment owed to Wyandanch’s daughter","eventTitle":"The court preserves the annual payment owed to Wyandanch’s daughter","start_year":1665,"sort_key":16650607,"dateLabel":"June 7, 1665","place":"Southold","coordinates":[-72.427,41.064],"reason":"The Southold order required East Hampton to continue the twenty-five-shilling annual payment associated with the Ogden agreement for the benefit of Wyandanch’s daughter and heir.","actionLabel":"The court preserves the annual payment owed to Wyandanch’s daughter"},{"label":"Quashawam participates in the Nicolls agreements","eventTitle":"Quashawam participates in the Nicolls agreements","start_year":1665,"sort_key":16651003,"dateLabel":"October 3–4, 1665","place":"Lower Manhattan / colonial council","coordinates":[-74.006,40.705],"reason":"The meetings addressed superior-sachem claims, Montauk boundaries, grazing, crop damage, and future land transactions. Nicolls reaffirmed the October 4 agreement in May 1668 over conflicting Scott arrangements.","actionLabel":"Quashawam participates in the Nicolls agreements"},{"label":"Quashawam’s testimony explains family interests in Cattawamnuck","eventTitle":"Quashawam’s testimony explains family interests in Cattawamnuck","start_year":1666,"sort_key":16660622,"dateLabel":"June 22, 1666","place":"Nissequogue River and Smithtown","coordinates":[-73.204,40.882],"reason":"The statement recorded by Thomas James describes relatives’ land interests and their expectation of sharing payment. Pauquatoun also recalled Wyandanch’s grandmother living there.","actionLabel":"Quashawam’s testimony explains family interests in Cattawamnuck"},{"label":"Ninigret reports Wyandanch’s daughter dead","eventTitle":"Ninigret reports Wyandanch’s daughter dead","start_year":1669,"sort_key":16690700,"dateLabel":"July 1669","place":"Newport, Rhode Island","coordinates":[-71.31,41.49],"reason":"Ninigret’s Rhode Island testimony placed the daughter’s death before his statement. It also asserted tribute claims rejected by the Montaukett leadership in November.","actionLabel":"Ninigret reports Wyandanch’s daughter dead"}]}};
